// Per column frame: whether the chat glow canvas is in #aside-chatting, the panel's computed background (60% while
// the glow is on, opaque when off) and the backgrounds still painted by its rows.
(() => JSON.stringify([...document.querySelectorAll(".cb-split-body > iframe")].map((f) => {
  const d = f.contentDocument, w = f.contentWindow, a = d.querySelector("#aside-chatting"), bg = (e) => e && w.getComputedStyle(e).backgroundColor;
  return {
    frame: [w.innerWidth, w.innerHeight], theme: d.documentElement.className, stats: w.ChzzkBestAmbient?.stats(),
    chatGlow: !!a?.querySelector(":scope > canvas.cb-ambient"), aside: bg(a),
    rows: [...(a?.children ?? [])].filter((e) => e.tagName !== "CANVAS").map(bg), title: bg(a?.querySelector(":scope > * > h2")), pinned: bg(a?.querySelector(':scope > * > [class*="_fixed_"]')),
  };
})))()

